-- AquaLens seed data. Generated by scripts/generate-seed.mjs.
-- REAL: 106 monitoring sites, environmental indicators and discharge series from the AquaConnect snapshot
--       (forecast 2026-09-28 to 2026-10-04). Screening outputs, not probabilities of ecological damage.
-- DEMO: citizen reports, photos, AI findings, expert reviews and notifications (illustrative only).
-- Safe to re-run: the AquaConnect rows and the demo reports are replaced; anything else is kept.

-- Remove the old Portland demo sites (indicators and discharge go with them) and refresh the demo reports.
delete from public.sites where id in ('S-101','S-102','S-103','S-104','S-105','S-106');
delete from public.observations where id in ('OBS-2041', 'OBS-2039', 'OBS-2036', 'OBS-2033', 'OBS-2030', 'OBS-2027', 'OBS-2024', 'OBS-2019', 'OBS-2015');
delete from public.notifications where id in ('N-1', 'N-2', 'N-3', 'N-4');
delete from public.environmental_indicators;
delete from public.discharge_series;

on conflict (id) do update set name = excluded.name, city = excluded.city, latitude = excluded.latitude, longitude = excluded.longitude, site_type = excluded.site_type, upstream_site_ids = excluded.upstream_site_ids, downstream_site_ids = excluded.downstream_site_ids, last_updated_at = excluded.last_updated_at, data_availability = excluded.data_availability, monitoring_priority = excluded.monitoring_priority, priority_class = excluded.priority_class, priority_score = excluded.priority_score;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;
